-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql (la tabla enemies).
--
-- Enemigos de Honkai: Star Rail: los 375 del juego (version 4.5), divididos en
-- jefes (110) y esbirros (265, de los que 113 son elites).
--
-- Fuentes:
--   Datos del propio juego (TurnBasedGameData, de Dimbreath) -> nombre y
--     descripcion oficiales en espanol, rango, debilidades, resistencias,
--     faccion y habilidades.
--   Nanoka (static.nanoka.cc) -> imagen de cada enemigo.
--
-- Un mismo enemigo aparece en el juego con varias versiones (por dificultad o
-- por contenido) que a veces cambian de debilidades: van juntas en una fila, y
-- las combinaciones distintas quedan en la columna variants.
--
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada.
--
-- Generado el 2026-09-15.

--
-- PARTE 2 de 3 (128 filas). El archivo entero no cabia en el SQL Editor:
-- ejecuta las 3 partes, en cualquier orden.

insert into public.enemies (
  id, game_id, name, name_en, category, rank, faction, description, image_url, weaknesses, resistances, variants, skills
)
values
  ('hsr-enemy-4034013', 'honkai-star-rail', 'Roballamas del Apocalipsis Extraviado', 'Flame Reaver of Doomsday Led Astray', 'jefe', 'jefe', null, 'Un espadachín sin nombre que llega con la marea oscura y busca incansablemente las Yescas de los Titanes. Nadie conoce su verdadera identidad.
Posee un poder increíble y sus habilidades con la espada son prácticamente perfectas. La obsesión y la locura se entrelazan en su filo. Fue el responsable de la destrucción del Soto de las Musas y Elisios.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4034010.webp', '["Físico","Hielo","Rayo","Cuántico"]'::jsonb, '[{"elemento":"Fuego","valor":40},{"elemento":"Viento","valor":40},{"elemento":"Imaginario","valor":40}]'::jsonb, null, '[{"nombre":"Nubarrón de la fatalidad","descripcion":"Inflige Daño Físico a un aliado y a los objetivos adyacentes.","tipo":"Habilidad","elemento":null},{"nombre":"Final del destino","descripcion":"Inflige Daño Físico a todos los aliados. Una parte de los PV reducidos de los objetivos golpeados se convierte en Corrosión.","tipo":"Habilidad","elemento":null},{"nombre":"Caminos mezclados","descripcion":"Recipiente Arruinado entra en el estado de Ofrenda conjunta.","tipo":"Habilidad","elemento":null},{"nombre":"Luto del inframundo","descripcion":"Lanza Nubarrón de la fatalidad o Final del destino a la vez que Recipiente Arruinado. Luego absorbe a Recipiente Arruinado.","tipo":"Habilidad","elemento":null},{"nombre":"Lamento moribundo","descripcion":"Obtiene Poder del desastre y entra en el estado Lamento moribundo. Lanza Sacrificio necesario en la siguiente acción.","tipo":"Habilidad","elemento":null},{"nombre":"Lamento silencioso","descripcion":"Obtiene Poder del desastre y entra en el estado Lamento silencioso. Lanza Abandono sin lágrimas en la siguiente acción.","tipo":"Habilidad","elemento":null},{"nombre":"Sacrificio necesario","descripcion":"Consume todas las acumulaciones de Poder del desastre e inflige varias veces una pequeña cantidad de Daño Físico a todos los aliados. Cuantas más acumulaciones de Poder del desastre consuma, más golpes de daño da. Luego inflige una pequeña cantidad de Daño Físico a todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Abandono sin lágrimas","descripcion":"Inflige Daño Físico a todos los aliados. Consume todas las acumulaciones de Poder del desastre e inflige adicionalmente una pequeña cantidad de Daño Físico varias veces. Cuantas más acumulaciones de Poder del desastre consuma, más veces inflige daño.","tipo":"Habilidad","elemento":null},{"nombre":"El dolor de la separación","descripcion":"Al lanzar Nubarrón de la fatalidad o Final del destino, invoca Recipiente Arruinado. Cuando el Recipiente Arruinado es eliminado, esta unidad pierde PV propios. Cuando vuelve a lanzar Nubarrón de la fatalidad o Final del destino, el Recipiente Arruinado que fue invocado por este ataque ataca junto a esta unidad. Luego esta unidad absorbe a Recipiente Arruinado.","tipo":"Talento","elemento":null},{"nombre":"Ofrendas perdidas","descripcion":"Al lanzar Lamento moribundo o Lamento silencioso, invoca Recipiente Arruinado. Cuando Roballamas del Apocalipsis Extraviado está en el estado de Rompegrilletes, si Recipiente Arruinado recibe un golpe letal, vuelve a invocar Recipiente Arruinado inmediatamente y reduce la Firmeza de Roballamas del Apocalipsis Extraviado.","tipo":"Talento","elemento":null},{"nombre":"Rompegrilletes","descripcion":"Entra en el estado Rompegrilletes. Invoca 4 Recipientes Arruinados y les aplica el estado de Cadenas.","tipo":"Habilidad","elemento":null},{"nombre":"Resurrección de la calamidad","descripcion":"Cuando se pierde la primera acumulación de Firmeza, se disipan todos los estados de control y entra en el estado Rompegrilletes. Además, realiza una acción inmediatamente. La Firmeza no puede reducirse por debajo de 1 antes de entrar en el estado de Rompegrilletes.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-2004014', 'honkai-star-rail', 'Señor de Espíritus', 'Soulhook Sovereign', 'jefe', 'jefe', null, 'Miembro de los Cazadores de Estelaron. Una hermosa asesina que siempre luce una sonrisa misteriosa. Es experta en usar varios tipos de armas y en manipular a la gente. También es quien trajo al Expreso Astral a donde está ahora para llevar a cabo un plan desconocido...', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2004010.webp', '["Físico","Fuego","Viento","Imaginario"]'::jsonb, '[{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":40},{"elemento":"Cuántico","valor":40}]'::jsonb, null, '[{"nombre":"Tumulto a medianoche","descripcion":"Inflige Daño de Rayo a un aliado determinado y tiene una probabilidad de causarle Electrocución.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Luna acariciadora","descripcion":"Inflige Daño de Rayo a un objetivo principal y a los aliados adyacentes. Si el objetivo principal está bajo el efecto de Electrocución, los adyacentes también se verán afectados por Electrocución.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Burla mordaz y silenciosa","descripcion":"Inflige Daño de Rayo a todos los aliados.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Encantadora de espíritus","descripcion":"Tiene una gran probabilidad de afectar con Dominación a un objetivo y adelantar su acción para que ataque inmediatamente a un aliado al azar.","tipo":"Habilidad","elemento":null},{"nombre":"El murmullo de los caídos","descripcion":"Inflige Daño de Rayo a un aliado determinado y tiene una probabilidad de causarle Electrocución. Además, inflige Daño de Rayo a todos los objetivos afectados por Electrocución.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Sugestión psicológica","descripcion":"Varios aliados entran en el estado de Sugestión psicológica y añaden Revelación en el orden de acción. Cuando ocurre la siguiente acción de Revelación, todos los personajes afectados por Sugestión psicológica entrarán en el estado de Dominación.","tipo":"Habilidad","elemento":null},{"nombre":"Temblor","descripcion":"Si el objetivo está bajo el efecto de Electrocución, inflige Daño de Electrocución una vez.","tipo":"Talento","elemento":null},{"nombre":"Crueldad","descripcion":"Lanza 1 ataque de Rayo adicional cuando un enemigo (que no sea él mismo) o un aliado afectado por Dominación ataca al aliado objetivo principal electrocutado.","tipo":"Talento","elemento":"Rayo"},{"nombre":"Suplente de marioneta","descripcion":"Aplica el efecto de Locura a las invocaciones.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Invocaespíritus","descripcion":"Invoca 2 enemigos de élite para asistirlo en combate. Cuando un aliado inflige daño a las invocaciones, el Señor de Espíritus pierde una cantidad de PV equivalente. Cuando se rompe la Debilidad de las invocaciones, su acción se retrasa de forma adicional. Cuando cualquiera de las invocaciones es eliminada, su tipo de Debilidad se implanta a otra invocación en el campo de batalla y obtiene el efecto de Mirada sangrienta.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-2034010', 'honkai-star-rail', 'Señor de la Guerra Borisin: Hoolay', 'Borisin Warhead: Hoolay', 'jefe', 'jefe', 'El Luofu de Xianzhou', 'Un líder de los borisin que cometió los diez pecados capitales y fue encarcelado para siempre en las profundidades de la Prisión de los Encadenados.
Con el odio acumulado durante setecientos años de presidio, el Señor de los Lobos desafía a todo el Luofu de Xianzhou tras fugarse de prisión. Pero parece que otro motivo se esconde detrás de sus acciones desquiciadas...', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2034010.webp', '["Físico","Fuego","Viento"]'::jsonb, '[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Fuego","Viento"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Colmillos de espadas rotas","descripcion":"Inflige Daño de Rayo a un aliado.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Garras de hierros cortados","descripcion":"Inflige Daño de Rayo a un aliado y a los aliados adyacentes.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Yermo vasto y estéril","descripcion":"Retrasa la acción de todos los demás objetivos (excepto él mismo) e inflige una pequeña cantidad de Daño de Rayo.","tipo":"Habilidad","elemento":null},{"nombre":"Asolación de la tormenta rugiente","descripcion":"Inflige Daño de Rayo a todos los aliados.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Persecución del lobo voraz","descripcion":"Inflige una gran cantidad de Daño de Rayo a un aliado y tiene una gran probabilidad de afectarlo con Miedo pertinaz.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Locura lunar del Señor de la Guerra","descripcion":"Después de que un enemigo ataque, aplica 1 acumulación de Sed de sangre a los enemigos que puedan entrar en el estado de Locura lunar. Cuando Sed de sangre alcanza cierta cantidad de acumulaciones, el enemigo entra en el estado de Locura lunar.\nEn el orden de acción aparece una cuenta regresiva de Locura lunar. Cuando comienza el turno de la cuenta regresiva, se disipa el estado de Locura lunar de todos los enemigos.","tipo":"Habilidad","elemento":null},{"nombre":"Lobo que aúlla a la luna","descripcion":"Cada vez que un enemigo lanza un ataque mientras Hoolay está en el estado de Locura lunar, le añade 1 acumulación de Rabia. Si Hoolay ataca, obtiene 1 acumulación adicional de Rabia. Cada vez que un aliado lanza un ataque, se reduce 1 acumulación de Rabia. Rabia tiene una cantidad inicial de acumulaciones. Cuando alcanza ciertas acumulaciones de Rabia, Hoolay lanza Persecución del lobo voraz y elimina todas las acumulaciones de Rabia. Cada vez que las acumulaciones de Rabia se reducen a 0 debido a los ataques de los personajes aliados, la Firmeza de Hoolay se reduce y las acumulaciones de Rabia se restablecen a una cierta cantidad.","tipo":"Habilidad","elemento":null},{"nombre":"Aullido acaudillador","descripcion":"Añade Congregar manada al orden de acción. Cada vez que Congregar manada actúa, invoca a un Soldado Lobo Garranegra o un Soldado Lobo Devoralunas. Cuando un enemigo entra en el estado de Locura lunar, la acción de Congregar manada se retrasa.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-2034015', 'honkai-star-rail', 'Señor de la Guerra Borisin: Hoolay (contaminado)', 'Borisin Warhead: Hoolay (Corrupted)', 'jefe', 'jefe', null, 'Un líder de los borisin que cometió los diez pecados capitales y fue encarcelado para siempre en las profundidades de la Prisión de los Encadenados.
Con el odio acumulado durante setecientos años de presidio, el Señor de los Lobos desafía a todo el Luofu de Xianzhou tras fugarse de prisión. Pero parece que otro motivo se esconde detrás de sus acciones desquiciadas...', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2034010.webp', '["Físico","Fuego","Viento"]'::jsonb, '[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Colmillos de espadas rotas","descripcion":"Inflige Daño de Rayo a un aliado.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Garras de hierros cortados","descripcion":"Inflige Daño de Rayo a un aliado y a los objetivos adyacentes.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Yermo vasto y estéril","descripcion":"Retrasa la acción de todos los demás objetivos (excepto él mismo) e inflige una pequeña cantidad de Daño de Rayo.","tipo":"Habilidad","elemento":null},{"nombre":"Asolación de la tormenta rugiente","descripcion":"Inflige Daño de Rayo a todos los aliados.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Persecución del lobo voraz","descripcion":"Inflige una gran cantidad de Daño de Rayo a un aliado y tiene una gran probabilidad de afectarlo con Miedo pertinaz.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Locura lunar del Señor de la Guerra","descripcion":"Después de que un enemigo ataque, aplica 1 acumulación de Sed de sangre a los enemigos que puedan entrar en el estado de Locura lunar. Cuando Sed de sangre alcanza cierta cantidad de acumulaciones, el enemigo entra en el estado de Locura lunar.\nEn el orden de acción aparece una cuenta regresiva de Locura lunar. Cuando comienza el turno de la cuenta regresiva, se disipa el estado de Locura lunar de todos los enemigos.","tipo":"Habilidad","elemento":null},{"nombre":"Lobo que aúlla a la luna","descripcion":"Cada vez que un enemigo lanza un ataque mientras Hoolay está en el estado de Locura lunar, le añade 1 acumulación de Rabia. Si Hoolay ataca, obtiene 1 acumulación adicional de Rabia. Cada vez que un aliado lanza un ataque, se reduce 1 acumulación de Rabia. Rabia tiene una cantidad inicial de acumulaciones. Cuando alcanza ciertas acumulaciones de Rabia, Hoolay lanza Persecución del lobo voraz y elimina todas las acumulaciones de Rabia. Cada vez que las acumulaciones de Rabia se reducen a 0 debido a los ataques de los personajes aliados, la Firmeza de Hoolay se reduce y las acumulaciones de Rabia se restablecen a una cierta cantidad.","tipo":"Habilidad","elemento":null},{"nombre":"Aullido acaudillador","descripcion":"Añade Congregar manada al orden de acción. Cada vez que Congregar manada actúa, invoca a un Soldado Lobo Garranegra o un Soldado Lobo Devoralunas. Cuando un enemigo entra en el estado de Locura lunar, la acción de Congregar manada se retrasa.","tipo":"Habilidad","elemento":null},{"nombre":"Aullido lupino","descripcion":"En la batalla aparece Lodo negro, que potencia al jefe. Tras la potenciación, Señor de la Guerra Borisin: Hoolay (contaminado) entra inmediatamente en el estado de Locura lunar y lanza Yermo vasto y estéril.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-2034012', 'honkai-star-rail', 'Señor de la Guerra Borisin: Hoolay (intacto)', 'Borisin Warhead: Hoolay (Complete)', 'jefe', 'jefe', null, 'Una proyección intacta creada por un código alterado. La referencia original es un líder de los borisin que cometió los diez pecados capitales y fue encarcelado para siempre en las profundidades de la Prisión de los Encadenados.
Con el odio acumulado durante setecientos años de presidio, el Señor de los Lobos desafía a todo el Luofu de Xianzhou tras fugarse de prisión. Pero parece que otro motivo se esconde detrás de sus acciones desquiciadas...', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2034010.webp', '["Físico","Fuego","Viento"]'::jsonb, '[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Colmillos de espadas rotas","descripcion":"Inflige Daño de Rayo a un aliado.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Garras de hierros cortados","descripcion":"Inflige Daño de Rayo a un aliado y a los objetivos adyacentes.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Yermo vasto y estéril","descripcion":"Retrasa la acción de todos los demás objetivos (excepto él mismo) e inflige una pequeña cantidad de Daño de Rayo.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Asolación de la tormenta rugiente","descripcion":"Inflige Daño de Rayo a todos los aliados y tiene una probabilidad de afectarlos con Miedo pertinaz.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Persecución del lobo voraz","descripcion":"Inflige una gran cantidad de Daño de Rayo a un aliado y tiene una gran probabilidad de afectarlo con Miedo pertinaz.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Locura lunar","descripcion":"Después de que un enemigo ataque, aplica 1 acumulación de Sed de sangre a los enemigos que puedan entrar en el estado de Locura lunar. Cuando Sed de sangre alcanza cierta cantidad de acumulaciones, el enemigo entra en el estado de Locura lunar.\nEn el orden de acción aparece una cuenta regresiva de Locura lunar. Cuando comienza el turno de la cuenta regresiva, se disipa el estado de Locura lunar de todos los enemigos.","tipo":"Habilidad","elemento":null},{"nombre":"Lobo que aúlla a la luna","descripcion":"Cada vez que un enemigo lanza un ataque mientras Hoolay está en el estado de Locura lunar, le añade 1 acumulación de Rabia. Si Hoolay ataca, obtiene 1 acumulación adicional de Rabia. Cada vez que un objetivo que no sea un enemigo lanza un ataque, se reduce 1 acumulación de Rabia. Rabia tiene una cantidad inicial de acumulaciones. Cuando alcanza ciertas acumulaciones de Rabia, Hoolay lanza Persecución del lobo voraz y elimina todas las acumulaciones de Rabia. Cada vez que las acumulaciones de Rabia se reducen a 0 debido a los ataques de los personajes aliados, la Firmeza de Hoolay se reduce y las acumulaciones de Rabia se restablecen a una cierta cantidad.","tipo":"Habilidad","elemento":null},{"nombre":"Aullido acaudillador","descripcion":"Añade Congregar manada al orden de acción. Cada vez que Congregar manada actúa, invoca a un Soldado Lobo Garranegra o un Soldado Lobo Devoralunas.","tipo":"Habilidad","elemento":null},{"nombre":"Llamada","descripcion":"Tras entrar en la fase 3, aumenta la VEL de Congregar manada y entra inmediatamente en el estado de Locura lunar.","tipo":"Habilidad","elemento":null},{"nombre":"Poder de la luna carmesí","descripcion":"Aumenta el daño que inflige Hoolay cada vez que usa Asolación de la tormenta rugiente.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-3004023', 'honkai-star-rail', 'Skott de las Mil Caras', 'Thousand-Faced Skott', 'jefe', 'jefe', null, 'Skott, que reunió todos los recursos de filmación para convertirse en el protagonista más grande de todos los protagonistas. Busca vengarse {F#de la}{M#del} Trazacaminos con mil apariencias distintas después de que un Servant dispersara su consciencia y su alma.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3004023.webp', '["Fuego","Hielo","Rayo","Imaginario"]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Perseverancia del lobo","descripcion":"Durante esta batalla, Skott de las Mil Caras comparte PV con todos los demás Skott.","tipo":"Habilidad","elemento":null},{"nombre":"Tentación del lobo","descripcion":"Añade Aullido del lobo solitario al orden de acción. Cada vez que Aullido del lobo solitario actúa, disipa todos los estados negativos de Control y estados de Ruptura de Debilidad de todos los Skotts. Además, cambia el estado Burla de todos los Skotts al estado Enloquecimiento y lanza Para el lobo solitario: Una vida miserable. Cada vez que se rompe la Debilidad de un Skott, la acción de Aullido del lobo solitario se retrasa ligeramente.","tipo":"Habilidad","elemento":null},{"nombre":"Para el lobo solitario: Una vida miserable","descripcion":"Aumenta el ATQ de todos los enemigos, reduce los pts. de habilidad básica y la energía de todos los aliados, y les inflige Daño Cuántico y Daño de Fuego, con una probabilidad de aplicarles Ralentización y una gran probabilidad de afectarlos con Quemadura.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-3004024', 'honkai-star-rail', 'Skott de las Mil Caras (contaminado)', 'Thousand-Faced Skott (Corrupted)', 'jefe', 'jefe', null, 'Skott, que reunió todos los recursos de filmación para convertirse en el protagonista más grande de todos los protagonistas. Busca vengarse {F#de la}{M#del} Trazacaminos con mil apariencias distintas después de que un Servant dispersara su consciencia y su alma.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3004023.webp', '["Fuego","Hielo","Rayo","Imaginario"]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Perseverancia del lobo","descripcion":"Durante esta batalla, Skott de las Mil Caras comparte PV con todos los demás Skott.","tipo":"Habilidad","elemento":null},{"nombre":"Tentación del lobo","descripcion":"Añade Aullido del lobo solitario al orden de acción. Cada vez que Aullido del lobo solitario actúa, disipa todos los estados negativos de Control y estados de Ruptura de Debilidad de todos los Skotts. Además, cambia el estado Burla de todos los Skotts al estado Enloquecimiento y lanza Para el lobo solitario: Una vida miserable. Cada vez que se rompe la Debilidad de un Skott, la acción de Aullido del lobo solitario se retrasa ligeramente.","tipo":"Habilidad","elemento":null},{"nombre":"Para el lobo solitario: Una vida miserable","descripcion":"Aumenta el ATQ de todos los enemigos, reduce los pts. de habilidad básica y la energía de todos los aliados, y les inflige Daño Cuántico y Daño de Fuego, con una probabilidad de aplicarles Ralentización y una gran probabilidad de afectarlos con Quemadura.","tipo":"Habilidad","elemento":null},{"nombre":"Trabajo pagado","descripcion":"En la batalla aparece Lodo negro, que potencia al jefe. Tras la potenciación, Skott Furioso (contaminado) lanza inmediatamente Horas extra del lobo.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-2035010', 'honkai-star-rail', 'Sombra de "Feixiao"', 'Shadow of "Feixiao"', 'jefe', 'jefe', 'El Luofu de Xianzhou', 'Hoolay, que ha usado la luna carmesí para escapar de la muerte, se ha manifestado en la forma de Feixiao y se sitúa frente a ella, como si de un espejo se tratara.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2033020.webp', '["Físico","Fuego","Cuántico"]'::jsonb, '[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Sable pistola: espada colmillo","descripcion":"Inflige Daño de Viento a un aliado.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Gran hacha: garra férrea","descripcion":"Inflige Daño de Viento a un aliado y tiene una gran probabilidad de afectarlo con Debilitación.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Ataduras celestes","descripcion":"Esta unidad se potencia a sí misma y obtiene una acción adicional.","tipo":"Habilidad","elemento":null},{"nombre":"Curtido en la tormenta","descripcion":"Genera Resonancia con todas las partes de la Bestia del Corazón Devoralunas y disipa su estado de Ruptura de Debilidad. No puede recibir ataques antes de actuar la próxima vez y, en su siguiente acción, lanza Barrer el cielo y tragar la tierra contra todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Barrer el cielo y tragar la tierra","descripcion":"Inflige una gran cantidad de Daño de Viento a todos los aliados y se potencia según las partes restantes que no tengan Ruptura de Debilidad. El daño de la habilidad aumenta por cada parte que no tenga Ruptura de Debilidad. Además, se añade el efecto de fortalecimiento de las partes correspondientes.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Tempestad pasajera","descripcion":"Inflige Daño de Viento a todos los aliados.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Ataque conjunto de la bestia interior","descripcion":"La acción adicional de la Sombra de \"Feixiao\" puede resonar con las partes de la Bestia del Corazón Devoralunas. La Resonancia permite a las partes de la Bestia del Corazón Devoralunas recuperar cierta Firmeza y además aumenta la Firmeza reducida al recibir un ataque. La siguiente acción se vuelve potenciada. La Resonancia de Cabeza Devoradora de Nebulosas tiene una gran probabilidad de afectar a todos los aliados con Cólera. La Resonancia de Garra Desgarradora de Planos tiene una gran probabilidad de aumentar adicionalmente el daño. La Resonancia de Cola Purgadora de Mundos tiene una gran probabilidad de afectar a todos los aliados con Debilitación.","tipo":"Talento","elemento":null},{"nombre":"Salvaguardia","descripcion":"Entra en el estado de Salvaguardia y reduce el daño que recibe cuando no se ha roto su Debilidad. Al romperse su Debilidad, su acción se retrasa adicionalmente y el daño que recibe después aumenta.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-5014014', 'honkai-star-rail', 'Superídolo Centro de Atención', 'Super Idol: Center of Attention', 'jefe', 'jefe', 'Fabulae', '¡Chispa, la streamer más popular de Planarcadia, comienza su directo! ¡Presencia esta noche la Gala Chispas en la que revelará su nueva imagen a sus fans!', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5014010.webp', '["Físico","Fuego","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":40},{"elemento":"Viento","valor":40}]'::jsonb, null, '[{"nombre":"¡A manipular el chat!","descripcion":"Cuando se disipa PK en directo, si todos los enemigos en el campo secundario han sido eliminados, el daño que reciben todos los enemigos aumenta, se retrasa su acción, se recuperan pts. de habilidad básica y Aha obtiene inmediatamente 1 turno adicional que cuenta como una cantidad fija de Chiste. Este turno no consume Chiste. Si al disiparse PK en directo no se han eliminado todos los enemigos en el campo secundario, inflige una gran cantidad de Daño Cuántico al personaje aliado que esté en el campo secundario y lo afecta con Enredo.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"¡Comentarios cargados!","descripcion":"Cuando se disipa PK en directo, si los enemigos en el campo secundario aún no han sido eliminados, inflige Daño Cuántico a todos los aliados y tiene una probabilidad de afectar con Comentarios negativos aleatorios a los objetivos atacados. Cuanto más alto sea el porcentaje de PV restante de los enemigos en el campo secundario, mayor es el daño infligido y mayor es la probabilidad de aplicar Comentarios negativos aleatorios.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"¡Duelo en línea!","descripcion":"Inflige Daño Cuántico a un aliado.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"¡A marcar el ritmo!","descripcion":"Inflige Daño Cuántico a todos los aliados.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"¡Toma el micrófono!","descripcion":"Activa PK en directo para elegir a un personaje aliado y enviarlo a combatir al campo secundario, mientras que los demás personajes permanecen en el campo principal brindando apoyo. Durante PK en directo, la habilidad de Exultación siempre atacará a los enemigos del campo secundario. En el orden de acción aparecerá una cuenta regresiva de PK en directo.\nPK en directo se disipa cuando se activa cualquiera de estas condiciones: la cuenta regresiva finaliza, el personaje aliado en el campo secundario es derrotado, todos los enemigos en el campo secundario son eliminados o no queda ningún personaje aliado que pueda combatir en dicho campo.","tipo":"Habilidad","elemento":null},{"nombre":"Directo promocional","descripcion":"Otorga el estado de Afluencia de espectadores a los enemigos que se encuentren en el campo secundario, adelanta su acción y aumenta su Prob. CRIT.","tipo":"Habilidad","elemento":null},{"nombre":"Ajuste del nivel de amistad","descripcion":"Después de activar PK en directo, los ataques a Puerto de Salida 1 aumentan la Popularidad aliada, mientras que los ataques a Puerto de Salida 2 reducen la Popularidad oponente. Cuando la Popularidad aliada aumenta, Puerto de Salida 1 adelanta su acción, y cuando la Popularidad oponente disminuye, Puerto de Salida 2 adelanta su acción.","tipo":"Talento","elemento":null},{"nombre":"Locura de los fans","descripcion":"Cuando se activa PK en directo, el daño que reciben los enemigos en el campo principal se reduce y obtiene inmunidad a estados negativos de Control. Cuando PK en directo se disipa, si todos los enemigos en el campo secundario han sido eliminados, se pierde este efecto. En caso contrario, se mantiene parte del efecto de reducción de daño según el porcentaje de PV restante de los enemigos en el campo secundario hasta que se active el siguiente PK en directo. Si sus PV se reducen a cierto porcentaje sin haber activado PK en directo, su acción se adelanta.","tipo":"Talento","elemento":null},{"nombre":"Superídolo","descripcion":"Al comenzar su turno, la Popularidad aliada y la Popularidad oponente se restablecen a su estado inicial.\nCuando los ataques hacen que la Popularidad aliada alcance el máximo o que la Popularidad oponente alcance el mínimo, se reducen los PV de todos los enemigos del campo secundario y los aliados obtienen cierta cantidad de Chiste. \nCuando se elimina a todos los enemigos del campo secundario, se reducen en gran medida la Firmeza y los PV de Superídolo Centro de Atención.","tipo":"Talento","elemento":null},{"nombre":"Streamer dedicado","descripcion":"Al comenzar la batalla, se encuentra en el estado de Bloqueo de Firmeza. Cuando se disipa el PK en directo, se disipa el estado de Bloqueo de Firmeza. Cuando se activa el PK en directo o cambia de fase, vuelve a entrar en el estado de Bloqueo de Firmeza.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-1014010', 'honkai-star-rail', 'Svarog', 'Svarog', 'jefe', 'jefe', 'Jarilo-VI', 'Antigua máquina del viejo mundo. Era una unidad de control automático que dejó el Equipo de Desarrollo de Geomédula. A diferencia de la mayoría de las máquinas, que no poseen inteligencia y solo ejecutan órdenes, Svarog es capaz de pensar por sí mismo pensamientos complejos.
Durante la batalla, Svarog invoca un brazo robótico que agarra y controla a sus enemigos y lanza ataques devastadores.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1014010.webp', '["Fuego","Rayo","Viento"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo","Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo","Viento","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Rayo","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Puño desterrador","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Rayo incinerador","descripcion":"Inflige Daño Físico a un aliado y retrasa la acción de ese aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Abrazo opresivo","descripcion":"Afecta con Confinamiento a un aliado. En este estado, el objetivo no puede actuar ni tampoco se puede elegir como objetivo de un ataque. Cuando se rompe la Debilidad del Brazo Robótico Auxiliar se disipa el estado de Confinamiento del aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Bombardeo eficiente","descripcion":"Inflige una gran cantidad de Daño Físico a todos los aliados y tiene una gran probabilidad de reducir la DEF de los objetivos atacados.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Explosión controlada","descripcion":"El Brazo Robótico Auxiliar explota e inflige una gran cantidad de Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Aviso de sobrecarga","descripcion":"El Brazo Robótico Auxiliar entra en estado de Límite de tiempo de sobrecarga y en la siguiente acción activa una Explosión controlada.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Despliegue adicional","descripcion":"Invoca al Brazo Robótico Auxiliar.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Bombardeo saturado","descripcion":"Inflige una gran cantidad de Daño Físico a todos los aliados y tiene una gran probabilidad de reducir la DEF de los objetivos atacados. Este estado negativo se puede acumular.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Amplificación de poder","descripcion":"El daño que infligen todos los enemigos aumenta ligeramente. El efecto de aumento de daño se puede acumular.","tipo":"Habilidad","elemento":null},{"nombre":"Refuerzos de emergencia","descripcion":"Invoca al Escarabajo Autómata y al Sabueso Autómata al azar.","tipo":"Habilidad","elemento":null},{"nombre":"Refuerzos estratégicos","descripcion":"Invoca al Huargo Autómata.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-1014011', 'honkai-star-rail', 'Svarog (intacto)', 'Svarog (Complete)', 'jefe', 'jefe', null, 'Una proyección intacta creada por un código alterado. La referencia original es una antigua máquina del viejo mundo. Era una unidad de control automático que dejó el Equipo de Desarrollo de Geomédula. A diferencia de la mayoría de las máquinas, que no poseen inteligencia y solo ejecutan órdenes, Svarog es capaz de pensar por sí mismo pensamientos complejos.
Durante la batalla, Svarog (intacto) invoca varios robots que agarran y controlan a sus enemigos y lanza ataques devastadores.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1014010.webp', '["Fuego","Rayo","Viento"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Puño desterrador","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Rayo incinerador","descripcion":"Inflige Daño Físico a un aliado y retrasa la acción de ese aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Abrazo opresivo","descripcion":"Afecta con Confinamiento a un aliado. En este estado, el objetivo no puede actuar ni tampoco se puede elegir como objetivo de un ataque. Cuando se rompe la Debilidad del Brazo Robótico Auxiliar se disipa el estado de Confinamiento del aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Bombardeo saturado","descripcion":"Inflige una gran cantidad de Daño Físico a todos los aliados y tiene una gran probabilidad de reducir la DEF de los objetivos atacados. Este estado negativo se puede acumular.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Explosión controlada","descripcion":"El Brazo Robótico Auxiliar explota e inflige una gran cantidad de Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Aviso de sobrecarga","descripcion":"El Brazo Robótico Auxiliar entra en estado de Límite de tiempo de sobrecarga y en la siguiente acción activa una Explosión controlada.","tipo":"Habilidad","elemento":null},{"nombre":"Despliegue adicional","descripcion":"Invoca al Brazo Robótico Auxiliar.","tipo":"Habilidad","elemento":null},{"nombre":"Amplificación de poder","descripcion":"El daño que infligen todos los enemigos aumenta ligeramente. El efecto de aumento de daño se puede acumular.","tipo":"Habilidad","elemento":null},{"nombre":"Refuerzos de emergencia","descripcion":"Invoca al Escarabajo Autómata y al Sabueso Autómata al azar.","tipo":"Habilidad","elemento":null},{"nombre":"Refuerzos estratégicos","descripcion":"Invoca al Huargo Autómata.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-2004020', 'honkai-star-rail', 'Teniente de los Nimbocaballeros - Yanqing', 'Cloud Knight Lieutenant: Yanqing', 'jefe', 'jefe', 'El Luofu de Xianzhou', 'Guardaespaldas del general Jing Yuan. A pesar de su corta edad, es un espadachín sin rival.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2004020.webp', '["Rayo","Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Rayo","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Rayo","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Rayo","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Viento arrebatado","descripcion":"Inflige Daño de Hielo a un aliado.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Regreso de la golondrina","descripcion":"Invoca 4 Espadas Voladoras y obtiene el efecto Formación de espadas, que aumenta su VEL. Las Espadas Voladoras obtienen Núcleo de la formación.","tipo":"Habilidad","elemento":null},{"nombre":"Apedreadracos","descripcion":"Inflige Daño de Hielo a un aliado determinado y tiene una gran probabilidad de congelar a ese aliado.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Himno rompeformaciones","descripcion":"Inflige Daño de Hielo a un aliado determinado y a los aliados adyacentes.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Filo de energía vital","descripcion":"Entra en el estado de Recarga. En la siguiente acción, utiliza Laceración torrencial contra todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Laceración torrencial","descripcion":"Inflige una gran cantidad de Daño de Hielo a todos los aliados.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Concentración de espadas","descripcion":"Fija como objetivo a un aliado y, después de 2 turnos, usa Corriente soñadora de nubes contra ese aliado.","tipo":"Habilidad","elemento":null},{"nombre":"Corriente soñadora de nubes","descripcion":"Inflige Daño de Hielo continuamente a un aliado. Después de usar esta habilidad, causa daño una cantidad de veces igual a la cantidad de Espadas Voladoras que haya en el campo de batalla. Después de usar esta habilidad, se eliminan todas las Espadas Voladoras que haya.","tipo":"Habilidad","elemento":"Hielo"}]'::jsonb),
  ('hsr-enemy-2004026', 'honkai-star-rail', 'Teniente de los Nimbocaballeros - Yanqing (contaminado)', 'Cloud Knight Lieutenant: Yanqing (Corrupted)', 'jefe', 'jefe', null, 'Guardaespaldas del general Jing Yuan. A pesar de su corta edad, es un espadachín sin rival.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2004020.webp', '["Rayo","Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Viento arrebatado","descripcion":"Inflige Daño de Hielo a un aliado. Yanqing y todas las Espadas Voladoras obtienen una acumulación de Luz escalofriante y el daño que infligen aumenta ligeramente.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Regreso de la golondrina","descripcion":"Invoca 4 Espadas Voladoras y obtiene el efecto Formación de espadas, que aumenta su VEL. Las Espadas Voladoras obtienen Núcleo de la formación.","tipo":"Habilidad","elemento":null},{"nombre":"Apedreadracos","descripcion":"Inflige Daño de Hielo a un aliado y tiene una gran probabilidad de congelar a ese aliado.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Himno rompeformaciones","descripcion":"Inflige Daño de Hielo a un aliado y a los aliados adyacentes.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Filo de energía vital","descripcion":"Entra en el estado de Recarga. En la siguiente acción, lanza Laceración torrencial contra todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Laceración torrencial","descripcion":"Inflige una gran cantidad de Daño de Hielo a todos los aliados.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Concentración de espadas","descripcion":"Fija como objetivo a un aliado y, después de dos turnos, lanza Corriente soñadora de nubes contra ese aliado.","tipo":"Habilidad","elemento":null},{"nombre":"Corriente soñadora de nubes","descripcion":"Inflige Daño de Hielo continuamente a un aliado. Después de lanzar esta habilidad, causa daño una cantidad de veces igual a la cantidad de Espadas Voladoras que haya en el campo de batalla. Después de lanzar esta habilidad, se eliminan todas las Espadas Voladoras que haya.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Nimbocaballero rompefilas","descripcion":"En la batalla aparece Lodo negro, que potencia al jefe. Tras la potenciación, Teniente de los Nimbocaballeros - Yanqing (contaminado) lanza inmediatamente Regreso de la golondrina.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-2004021', 'honkai-star-rail', 'Teniente de los Nimbocaballeros - Yanqing (intacto)', 'Cloud Knight Lieutenant: Yanqing (Complete)', 'jefe', 'jefe', null, 'Una proyección intacta creada por un código alterado. La referencia original es el guardaespaldas del general Jing Yuan, un talentoso espadachín que aún no ha alcanzado la mayoría de edad.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2004020.webp', '["Rayo","Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Rayo","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Rayo","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Viento arrebatado","descripcion":"Inflige Daño de Hielo a un aliado. Yanqing y todas las Espadas Voladoras obtienen una acumulación de Luz escalofriante y el daño que infligen aumenta ligeramente.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Regreso de la golondrina","descripcion":"Invoca 4 Espadas Voladoras y obtiene el efecto Formación de espadas, que aumenta su VEL. Las Espadas Voladoras obtienen Núcleo de la formación. En la tercera fase, otorga adicionalmente Calvario a una cierta cantidad de Espadas Voladoras.","tipo":"Habilidad","elemento":null},{"nombre":"Apedreadracos","descripcion":"Inflige Daño de Hielo a un aliado y tiene una gran probabilidad de congelar a ese aliado.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Himno rompeformaciones","descripcion":"Inflige Daño de Hielo a un aliado y a los aliados adyacentes.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Filo de energía vital","descripcion":"Entra en el estado de Recarga. En la siguiente acción, utiliza Laceración torrencial contra todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Laceración torrencial","descripcion":"Inflige una gran cantidad de Daño de Hielo a todos los aliados.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Concentración de espadas","descripcion":"Fija como objetivo a un aliado y, después de 2 turnos, usa Corriente soñadora de nubes contra ese aliado.","tipo":"Habilidad","elemento":null},{"nombre":"Corriente soñadora de nubes","descripcion":"Inflige Daño de Hielo continuamente a un aliado. Después de usar esta habilidad, causa daño una cantidad de veces igual a la cantidad de Espadas Voladoras que haya en el campo de batalla. Después de usar esta habilidad, se eliminan todas las Espadas Voladoras que haya.","tipo":"Habilidad","elemento":"Hielo"}]'::jsonb),
  ('hsr-enemy-2004023', 'honkai-star-rail', 'Teniente de los Nimbocaballeros: Yanqing (ilusión)', 'Cloud Knight Lieutenant: Yanqing (Illusion)', 'jefe', 'jefe', null, 'Guardaespaldas del general Jing Yuan. A pesar de su corta edad, es un espadachín sin rival. Esta entidad es una ilusión basada en tus recuerdos.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2004020.webp', '["Rayo","Viento","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":40},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":60}]'::jsonb, null, '[{"nombre":"Viento arrebatado","descripcion":"Inflige Daño de Hielo a un aliado y hace que todas las Espadas Voladoras (ilusión) lancen ataques que infligen daño extra.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Regreso de la golondrina","descripcion":"Invoca 4 Espadas Voladoras (ilusión) y obtiene el efecto de Formación de espadas, que aumenta su VEL. Las Espadas Voladoras (ilusión) solo se pueden eliminar cuando se rompe su Debilidad, momento en el que su Debilidad se transfiere a otra de las Espadas Voladoras restantes al azar. Después de romper la Debilidad de todas las Espadas Voladoras (ilusión), el efecto de Formación de espadas se disipa.","tipo":"Habilidad","elemento":null},{"nombre":"Apedreadracos","descripcion":"Inflige Daño de Hielo a un aliado y tiene una gran probabilidad de congelar a ese aliado.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Himno rompeformaciones","descripcion":"Inflige Daño de Hielo a un aliado y a los aliados adyacentes.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Filo de energía vital","descripcion":"Entra en el estado de Recarga. En la siguiente acción, utiliza Laceración torrencial contra todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Laceración torrencial","descripcion":"Inflige una gran cantidad de Daño de Hielo a todos los aliados.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Concentración de espadas","descripcion":"Fija como objetivo a un aliado y, después de 2 turnos, usa Corriente soñadora de nubes contra ese aliado.","tipo":"Habilidad","elemento":null},{"nombre":"Corriente soñadora de nubes","descripcion":"Inflige continuamente una gran cantidad de Daño de Hielo a un aliado.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Remolino de espadas sin sombra","descripcion":"Todos los ataques de Yanqing y sus Espadas Voladoras (ilusión) aplican Espina de escarcha a los aliados atacados, lo que aumenta el Daño de Hielo que reciben.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-1004015', 'honkai-star-rail', 'Topaz (ilusión)', 'Topaz Illusion', 'jefe', 'jefe', null, 'Una experta en inversiones, extrovertida y social. Es una de las directoras del Departamento de Inversiones Estratégicas de la Corporación y líder del equipo especial de fiscalización de deudas.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1004010.webp', '["Fuego","Rayo","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":40},{"elemento":"Hielo","valor":60},{"elemento":"Viento","valor":40},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Escalofrío perforahuesos","descripcion":"Inflige Daño de Hielo a un aliado.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Presagio de la Edad de Hielo","descripcion":"Invoca a 2 Pica Glacial.","tipo":"Habilidad","elemento":null},{"nombre":"Castigo del invierno eterno","descripcion":"Inflige una gran cantidad de Daño de Hielo a todos los aliados.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Furia de los santos de la tundra","descripcion":"Entra en el estado de Recarga. En su siguiente acción, lanza Castigo del invierno eterno contra todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Frío intensificado","descripcion":"Por cada objetivo aliado afectado por Congelación, aumenta ligeramente su daño infligido y el de las criaturas invocadas. El efecto de aumento de daño se puede acumular.","tipo":"Talento","elemento":null},{"nombre":"Escarcha aprisionada","descripcion":"Inflige Daño de Hielo a un aliado y tiene una gran probabilidad de congelar a ese objetivo aliado.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Hielo reverberante","descripcion":"Inflige Daño de Hielo a un aliado congelado y a los aliados adyacentes y disipa el estado de Congelación del objetivo principal. Si alguno de los aliados adyacentes está congelado, vuelve a usar esta habilidad contra el objetivo principal.","tipo":"Habilidad","elemento":"Hielo"}]'::jsonb),
  ('hsr-enemy-3004021', 'honkai-star-rail', 'Truco del Fuegoplátano', 'Blaznana Monkey Trick', 'jefe', 'jefe', null, 'Miembros de la Compañía Dulces Sueños cuyas mentes se han visto nubladas por la sombra de los árboles del Bosque Buscatávico. Llevan consigo un virus memético que ha dado fruto en el Veleibosque y se dedican a extender el credo del Monito Duermeplátano y las bananeces del Dr. Primitivo.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3004020.webp', '[]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Orgullo de la manada de monos","descripcion":"Durante esta batalla, Truco del Fuegoplátano comparte PV con todos los miembros de la Oficina Platanoacadémica.","tipo":"Habilidad","elemento":null},{"nombre":"Platanorario de clases","descripcion":"Añade Cena de fin de curso al orden de acción. Cada vez que Cena de fin de curso actúa, disipa todos los estados negativos de Control y estados de Ruptura de Debilidad de todos los miembros de la Oficina Platanoacadémica. Además, cambia el estado Canal del descanso de todos los miembros de la Oficina Platanoacadémica al estado Canal de la clase y lanza Para el doctor: Presentación de informe bananacadémico.","tipo":"Habilidad","elemento":null},{"nombre":"Para el doctor: Presentación de informe bananacadémico","descripcion":"Aumenta el ATQ de todos los enemigos, reduce los pts. de habilidad básica y la energía de todos los aliados, y les inflige Daño Cuántico y Daño de Fuego, con una probabilidad de aplicarles Ralentización y una gran probabilidad de afectarlos con Quemadura.","tipo":"Habilidad","elemento":null},{"nombre":"Examen de tanteo","descripcion":"Cuando el estado Canal de la clase de los enemigos se convierte en Canal del descanso rompiendo su Debilidad o acumulando cómputo, se reduce la Firmeza de Truco del Fuegoplátano. Al atacar a cualquier enemigo con Ruptura de Debilidad, la Firmeza de Truco del Fuegoplátano se reduce ligeramente. Cuando se rompe la Debilidad de Truco del Fuegoplátano, la Debilidad de todos los enemigos se rompe, y Truco del Fuegoplátano entra en el estado de Brecha de salvaguardia.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4014016', 'honkai-star-rail', 'Vencedor, Fortaleza, Señor del Conflicto', 'Victor, Acropolis, and Lord of Strife', 'jefe', 'jefe', null, 'Un partidario del Conflicto. Su locura ha domado aquella alma tenaz, y su maestro permanece inquebrantable desde entonces.
Como cántico de batalla y el bóreas, blande su lanza con decisión: para exterminar a los enemigos, para forjar a los soldados, para entregar gloria, respeto y determinación a su amigo y salvador.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4014010.webp', '["Hielo","Rayo","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Lanza de rayos del firmamento","descripcion":"Inflige una pequeña cantidad de Daño Imaginario a un aliado.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Espina desgarramundos","descripcion":"Inflige una pequeña cantidad de Daño Imaginario a un aliado y a los objetivos adyacentes.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Corte del río Estigia","descripcion":"Inflige Daño Imaginario a un aliado.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Supervivientes en aguas muertas","descripcion":"Inflige Daño Imaginario a un aliado.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Llamas de guerra interminables","descripcion":"Inflige Daño Imaginario a todos los aliados.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Pira de las tumbas altas","descripcion":"Inflige Daño Imaginario a todos los aliados.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Lanza hiendecielos","descripcion":"Inflige continuamente una pequeña cantidad de Daño Imaginario a objetivos aliados al azar.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Cremación del día y la noche","descripcion":"Inflige continuamente una pequeña cantidad de Daño Imaginario a objetivos aliados al azar.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Calamidad eterna","descripcion":"Inflige Daño Imaginario a todos los aliados y les aplica Gloria. Además, obtiene Cuerpo titánico. Cuando las acumulaciones de Cuerpo titánico llegan a 0, su acción se retrasa, se inflige una gran cantidad de Daño Imaginario y recupera energía para todos los aliados. Mientras tiene Cuerpo titánico, el daño que inflige en el siguiente ataque aumenta en gran medida y tiene una gran probabilidad de afectar con Prisión a todos los objetivos atacados.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Reinos arrasados, legiones aplastadas","descripcion":"Inflige a todos los aliados una gran cantidad de Daño Imaginario. El daño se reparte equitativamente entre los objetivos.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Protector de la polis","descripcion":"Tiene cierta cantidad de acumulaciones de Armadura de guerra, que reduce el daño que recibe. Tras recibir un ataque, la cantidad de acumulaciones de Armadura de guerra disminuye en 1. Cuando las acumulaciones llegan a 0, Armadura de guerra se destruye, inflige una gran cantidad de Daño Imaginario a esta unidad y retrasa su acción. El aliado que destruye Armadura de guerra recupera energía. Cuando esta unidad es atacada después de que se haya destruido su Armadura de guerra, recibe de forma adicional una pequeña cantidad de Daño Imaginario. Armadura de guerra recupera todas sus acumulaciones cuando termina el turno de esta unidad.","tipo":"Talento","elemento":null},{"nombre":"Es mejor morir en la batalla, no hay regreso triunfante","descripcion":"Al lanzar Calamidad eterna, aplica Gloria a todos los aliados. Cada acumulación de Gloria aumenta el daño que infligen los objetivos e incrementa su recuperación de energía. Al lanzar la habilidad básica o la habilidad definitiva, pueden acumular Gloria. Tras la siguiente acción de Vencedor, Fortaleza, Señor del Conflicto, se disipa el estado de Gloria de todos los aliados.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3003010', 'honkai-star-rail', 'Achicharrado de la Compañía Teatral de Terrores', 'Dreamjolt Troupe''s Beyond Overcooked', 'esbirro', 'elite', 'Compañía Teatral de Terrores', 'Máquina de servicio de Colonipenal que perdió el control debido a las interferencias emocionales en el paisaje onírico.
Era un robot de cocina y, tras perder el control, sigue escupiendo fuego para asar ingredientes e intentando abrasar a los comensales.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3003010.webp', '["Fuego","Rayo","Viento"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo","Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Rayo","Viento","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo","Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Fuego","Rayo","Viento"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":[],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":40},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":40}]}]'::jsonb, '[{"nombre":"Cuchara vigorosa","descripcion":"Inflige Daño de Fuego a un aliado.","tipo":"Habilidad","elemento":"Fuego"},{"nombre":"Zarandeo de remolino","descripcion":"Inflige una pequeña cantidad de Daño de Fuego a un aliado y a los objetivos adyacentes.","tipo":"Habilidad","elemento":"Fuego"},{"nombre":"Encendido de horno","descripcion":"Entra en el estado de Recarga. Si en la siguiente acción Horno en calentamiento no ha alcanzado cierta cantidad de acumulaciones, lanza Salteado ardiente y elimina todas las acumulaciones de Horno en calentamiento.","tipo":"Habilidad","elemento":"Fuego"},{"nombre":"Salteado ardiente","descripcion":"Inflige una gran cantidad de Daño de Fuego a todos los aliados.","tipo":"Habilidad","elemento":"Fuego"},{"nombre":"Accidente en la cocina","descripcion":"Tras entrar en el estado de Recarga, cuando alcanza cierta cantidad de acumulaciones de Horno en calentamiento, inflige una gran cantidad de Daño de Fuego a todos los enemigos y reduce su propia DEF. Al mismo tiempo, elimina todas las acumulaciones de Horno en calentamiento.","tipo":"Habilidad","elemento":"Fuego"},{"nombre":"Festín al fuego","descripcion":"Cuando no se encuentra en estado de Recarga, realiza una acción inmediatamente cuando Horno en calentamiento alcanza cierta cantidad de acumulaciones, y lanza Encendido de horno.","tipo":"Talento","elemento":null},{"nombre":"Horno infernal","descripcion":"Cuando esta unidad lanza un ataque, tiene una probabilidad de afectar con Ralentización al objetivo. Cuando esta unidad es atacada o recibe Daño con el tiempo, obtiene 1 acumulación de Horno en calentamiento.","tipo":"Talento","elemento":null},{"nombre":"Estallido de horno","descripcion":"Entra en el estado de Recarga. Hasta que Horno en calentamiento no haya alcanzado cierta cantidad de acumulaciones, usará Salteado ardiente en cada acción. Cuando se encuentra en estado de Recarga, reduce las acumulaciones actuales de Horno en calentamiento.","tipo":"Habilidad","elemento":"Fuego"}]'::jsonb),
  ('hsr-enemy-3003012', 'honkai-star-rail', 'Achicharrado de la Compañía Teatral de Terrores (error)', 'Dreamjolt Troupe''s Beyond Overcooked (Bug)', 'esbirro', 'elite', null, 'Una proyección falsa creada por un código alterado. La referencia original es una máquina de servicio de Colonipenal que perdió el control debido a las interferencias emocionales en el paisaje onírico.
